"""Build the local 20 November shooting package from preserved sources."""
from pathlib import Path
from io import BytesIO
import json,re,subprocess,shutil,hashlib
from PIL import Image,ImageDraw,ImageOps

ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist'
VIDEO={v['id']:{**v, 'file':str(ROOT/v['file'])} for v in json.loads((ROOT/'sources/videos.json').read_text())}
PROVENANCE=[]
DOCS=sorted((ROOT/'sources/text').glob('*.txt'))

def text(i): return next(p for p in DOCS if p.name.startswith(f'{i:02d}-')).read_text()
def timestamp(t): return f'{int(t)//60}:{t%60:04.1f}'.replace('.',',')
def span(a,b):
 def t(n): return f'{int(n)//60}:{int(n)%60:02d}'+(',5' if n%1 else '')
 return t(a)+'–'+t(b)
def source(key,t,label,setup,check,crop=None,mask=None):
 return dict(kind='source',video=key,second=t,label=label,setup=setup,check=check,crop=crop,mask=mask)
def photo(key,label,setup,check):
 return dict(kind='photo',photo=key,label=label,setup=setup,check=check)
def draft(sheet,panel,label,setup,check):
 return dict(kind='draft',sheet=sheet,panel=panel,label=label,setup=setup,check=check)
def scene(start,end,title,action,*visuals,role=None):
 return dict(time=span(start,end),title=title,text=action,visuals=list(visuals),**({'role':role} if role else {}))
def script_for(title,setup,frames,ending=''):
 return '\n\n'.join([title,setup,*[f"{f['time']} · {f['title']}\n{f['text']}" for f in frames],ending])
LIGHT='Все три источника включены. Слева от камеры 50–60%, справа белый CCT 5000–5600 К, начать с 5200 К. WB и экспозицию зафиксировать по карте рядом с лицом статуи. На коже и белых деталях сохраняем естественный цвет.'
PRODUCT='Вертикаль 9:16. Белый акрил на предметном столе, крутилка по центру. Полки оставляем позади в мягком расфокусе. Паша в тёмной однотонной футболке, руки в чистых чёрных перчатках. '+LIGHT
HOLD='Каждое действие записать с секундой запаса до и после. Чистые повороты и детали держать 6–8 секунд на дубль. На новом ракурсе отдельно поставить и зафиксировать фокус.'
